// Characterization tests: pin CURRENT behaviour of order totals, quirks included.
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const PRICES = { A: 10, B: 25, C: 33.33, D: 0.1, E: 100, F: 100.01, G: 9.99, H: 1.05 }

async function withApp(fn) {
  const pricing = { priceOf: async (sku) => PRICES[sku] }
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { return await fn(base) } finally { await new Promise((r) => server.close(r)) }
}

const post = (base, items) =>
  fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })

const cases = [
  // [label, items, expected total]
  ['single item, no discount', [{ sku: 'A', qty: 1 }], 10],
  ['multiple lines summed', [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }], 45],
  ['exactly 100 gets no discount', [{ sku: 'A', qty: 10 }], 100],
  ['just over 100 gets 10% off then floors (100.01 -> 90)', [{ sku: 'F', qty: 1 }], 90],
  ['101 -> 90.9 floors to 90', [{ sku: 'A', qty: 10 }, { sku: 'H', qty: 1 }].slice(0, 1).concat([{ sku: 'D', qty: 10 }]), 90],
  ['200 -> 180', [{ sku: 'E', qty: 2 }], 180],
  ['large order 1000 -> 900', [{ sku: 'E', qty: 10 }], 900],
  ['discount applies to whole order, not just the excess', [{ sku: 'B', qty: 5 }], 112],
  ['fractional prices floored without discount (3 x 9.99 = 29.97 -> 29)', [{ sku: 'G', qty: 3 }], 29],
  ['fractional prices floored with discount (4 x 33.33 = 133.32 -> 119.988 -> 119)', [{ sku: 'C', qty: 4 }], 119],
  ['zero quantity contributes nothing', [{ sku: 'A', qty: 0 }], 0],
]

for (const [label, items, expected] of cases) {
  test(`total: ${label}`, () => withApp(async (base) => {
    const res = await post(base, items)
    assert.equal(res.status, 201)
    const order = await res.json()
    assert.equal(order.total, expected)
    assert.deepEqual(order.items, items)
  }))
}

